#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define QUEUE_CAP 5

static long items[QUEUE_CAP];
static int head = 0;   /* index of the front element */
static int count = 0;  /* number of elements currently stored */

static inline int next_index(int idx) {
    return (idx + 1) % QUEUE_CAP;
}

static bool enqueue(long v) {
    if (count >= QUEUE_CAP) return false;
    int tail = (head + count) % QUEUE_CAP;
    items[tail] = v;
    ++count;
    return true;
}

static long dequeue(void) {
    long v = items[head];
    head = next_index(head);
    --count;
    return v;
}

static long front(void) {
    return items[head];
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        const char *cmd = argv[i];
        if (cmd[0] == 'E' && cmd[1] != '\0') {
            char *endptr;
            long val = strtol(cmd + 1, &endptr, 10);
            if (*endptr != '\0') {
                puts("ERR");
                continue;
            }
            if (enqueue(val)) {
                printf("ENQ %ld\n", val);
            } else {
                puts("FULL");
            }
            continue;
        }
        if (strcmp(cmd, "D") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long v = dequeue();
                printf("DEQ %ld\n", v);
            }
            continue;
        }
        if (strcmp(cmd, "F") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                printf("FRONT %ld\n", front());
            }
            continue;
        }
        puts("ERR");
    }
    return 0;
}
